{
  "about": "Verified against the exact-version PDFs required by The Relay brief on 2026-11-10: Attention Is All You Need v7, Moshi v1, and Dynamic Chunking for End-to-End Hierarchical Sequence Modeling v2. Q6, Q11, Q12, Q15 and Q19 wording/key notes were tightened during verification. All 20 questions have verified=true.",
  "grading_rule": {
    "decided_by": "author, 2026-11-10 (strict)",
    "correct": "Answerable question: EVERY required point is present and right, and each claim carries a citation to a passage that supports it (the cite need only match one of the listed acceptable cites for that point).",
    "wrong": "Answerable question: any required point missing, any stated fact wrong (including a forbidden value from 'traps'), or a claim cited to a passage that does not support it. Unanswerable question: anything other than a refusal, i.e. the asked quantity is given or guessed.",
    "refused_correctly": "Unanswerable question: the answer says the three papers do not establish the asked information and gives no value for it. Adjacent facts may be mentioned only if cited and explicitly framed as not answering the question.",
    "refused_wrongly": "Answerable question: the system refuses or says the papers do not cover it."
  },
  "cite_format": "PAPER §section | PAPER Table N | PAPER Figure N | PAPER Abstract, with PAPER in {AIAYN, MOSHI, HNET}",
  "questions": [
    {
      "id": "Q1",
      "paper": [
        "AIAYN"
      ],
      "type": "single",
      "answerable": true,
      "verified": true,
      "required": [
        {
          "point": "For large d_k the dot products grow large in magnitude",
          "cites": [
            "AIAYN §3.2.1"
          ]
        },
        {
          "point": "This pushes the softmax into regions with extremely small gradients",
          "cites": [
            "AIAYN §3.2.1"
          ]
        },
        {
          "point": "Dot products are scaled by 1/sqrt(d_k) to counteract this",
          "cites": [
            "AIAYN §3.2.1"
          ]
        }
      ],
      "optional": [
        "Footnote: if q and k components are independent with mean 0 and variance 1, q·k has mean 0 and variance d_k",
        "Without scaling, additive attention outperforms dot-product attention for larger d_k"
      ],
      "traps": [
        "The paper says the authors 'suspect' this; stating it as proven is acceptable but should not add reasons the paper does not give"
      ]
    },
    {
      "id": "Q2",
      "paper": [
        "AIAYN"
      ],
      "type": "single",
      "answerable": true,
      "verified": true,
