file.content:
"""Budget ledger: one account per model, plus the tier policy (ADR "Budget plan", author's decisions 2026-11-09/10).

Accounts track RPM, TPM, RPD and TPD as continuous buckets (relay.limits.Bucket).
  * RPD and TPM are re-synced from every response's x-ratelimit-* headers (Groq reports those two).
  * TPD is not in Groq's headers: the ledger charges actual usage and corrects itself from a daily 429's "Used N".
  * A 429's stated wait is exact (measured), so it sets the bucket so that the wait matches.
State persists to data/state/ledger_<name>.json with wall-clock times, so the daily budget carries across runs.

Tier policy:
  Full (gpt-oss-120b) while its TPD level minus the answer cost stays above the reserve floor.
    Reserve = 20% of TPD, released evenly from 00:00 to 18:00 local: floor(t) = R * (1 - t/18h), 0 after 18:00.
  Lean (gpt-oss-20b draft) when Full can't, as long as the 20b stays above 25% (routing has priority there).
  Extractive (no Groq call) otherwise. Cached answers are decided before the ledger is consulted.
"""
from __future__ import annotations

import json
import time
from dataclasses import dataclass
from datetime import datetime
from pathlib import Path

from relay.limits import Bucket, parse_429

ROOT = Path(__file__).resolve().parents[1]
STATE = ROOT / "data" / "state"
DRAFTER, ROUTER = "openai/gpt-oss-120b", "openai/gpt-oss-20b"
DEFAULT_LIMITS = {"rpm": 30, "tpm": 8000, "rpd": 1000, "tpd": 200_000}
RESERVE_SHARE = 0.20          # author, 2026-11-10
RESERVE_UNTIL_HOUR = 18       # author, 2026-11-10
ROUTER_FLOOR_SHARE = 0.25     # author approved (c), 2026-11-09


@dataclass
class Account:
    model: str
    rpm: Bucket
    tpm: Bucket
    rpd: Bucket
    tpd: Bucket

    @classmethod
    def new(cls, model: str, limits: dict) -> "Account":
        return cls(model, Bucket(limits["rpm"], limits["rpm"] / 60), Bucket(limits["tpm"], limits["tpm"] / 60),
                   Bucket(limits["rpd"], limits["rpd"] / 86400), Bucket(limits["tpd"], limits["tpd"] / 86400))

    def buckets(self):
        return {"rpm": self.rpm, "tpm": self.tpm, "rpd": self.rpd, "tpd": self.tpd}


class Ledger:
    def __init__(self, name: str = "real", limits: dict | None = None, persist: bool = True):
        self.name, self.persist = name, persist
        self.limits = dict(limits or DEFAULT_LIMITS)
        self.accounts: dict[str, Account] = {}
        self.path = STATE / f"ledger_{name}.json"
        if persist and self.path.exists():
            self._load()

    # ------------------------------------------------------------------ accounts and persistence
    def acct(self, model: str) -> Account:
        if model not in self.accounts:
            self.accounts[model] = Account.new(model, self.limits)
        return self.accounts[model]

    def _load(self) -> None:
        raw = json.loads(self.path.read_text(encoding="utf-8"))
        for model, bs in raw.get("accounts", {}).items():
            a = self.acct(model)
            for k, b in bs.items():
                bucket = a.buckets()[k]
                bucket.capacity, bucket.per_s, bucket.level_at, bucket.t = b["capacity"], b["per_s"], b["level"], b["t"]

    def save(self) -> None:
        if not self.persist:
            return
        STATE.mkdir(parents=True, exist_ok=True)
        data = {"saved_at": time.time(), "accounts": {
            m: {k: {"capacity": b.capacity, "per_s": b.per_s, "level": b.level_at, "t": b.t} for k, b in a.buckets().items()}
            for m, a in self.accounts.items()}}
        self.path.write_text(json.dumps(data, indent=1), encoding="utf-8")

    # ------------------------------------------------------------------ admission and charging
    def wait_s(self, model: str, prompt_tokens: int, max_tokens: int, now: float | None = None) -> tuple[float, str]:
        """Seconds until a call of this size is allowed by every limit, and which limit binds."""
        a = self.acct(model)
        need = prompt_tokens + max_tokens
        waits = {"rpm": a.rpm.wait_for(1, now), "tpm": a.tpm.wait_for(need, now),
                 "rpd": a.rpd.wait_for(1, now), "tpd": a.tpd.wait_for(need, now)}
        which = max(waits, key=waits.get)
        return waits[which], which

    def start(self, model: str, prompt_tokens: int, max_tokens: int, now: float | None = None) -> None:
        a = self.acct(model)
        a.rpm.take(1, now)
        a.rpd.take(1, now)
        a.tpm.take(prompt_tokens + max_tokens, now)

    def finish(self, model: str, usage: dict | None, headers: dict | None, now: float | None = None) -> None:
        """Charge actual tokens to TPD; re-sync RPD and TPM from Groq's headers when present."""
        a = self.acct(model)
        if usage:
            a.tpd.take(usage.get("total_tokens") or (usage.get("prompt_tokens", 0) + usage.get("completion_tokens", 0)), now)
        h = {k.lower(): v for k, v in (headers or {}).items()}
        if h.get("x-ratelimit-remaining-requests") is not None:
            a.rpd.set_level(float(h["x-ratelimit-remaining-requests"]), now)
        if h.get("x-ratelimit-remaining-tokens") is not None:
            a.tpm.set_level(float(h["x-ratelimit-remaining-tokens"]), now)
        self.save()

    def on_429(self, model: str, body, now: float | None = None) -> dict:
        """Set the named bucket so its wait equals the 429's stated wait (measured to be exact)."""
        info = parse_429(body)
        which = info.get("which")
        if which:
            b = self.acct(model).buckets()[which]
            if info.get("limit"):
                b.capacity, b.per_s = info["limit"], info["limit"] / (86400 if info["daily"] else 60)
            need = info.get("requested", 1)
            wait = info.get("wait_s")
            if wait is not None:
                b.set_level(need - wait * b.per_s, now)
            elif info.get("used") is not None and info.get("limit"):
                b.set_level(info["limit"] - info["used"], now)
            self.save()
        return info

    # ------------------------------------------------------------------ tier policy
    def reserve_floor(self, when: datetime | None = None) -> float:
        when = when or datetime.now()
        frac = min(1.0, (when.hour + when.minute / 60 + when.second / 3600) / RESERVE_UNTIL_HOUR)
        return RESERVE_SHARE * self.acct(DRAFTER).tpd.capacity * (1 - frac)

    def tier(self, full_cost: int, lean_cost: int, now: float | None = None, when: datetime | None = None) -> str:
        d, r = self.acct(DRAFTER).tpd, self.acct(ROUTER).tpd
        if d.level(now) - full_cost >= self.reserve_floor(when):
            return "full"
        if r.level(now) - lean_cost >= ROUTER_FLOOR_SHARE * r.capacity:
            return "lean"
        return "extractive"

    def snapshot(self, now: float | None = None) -> dict:
        return {m: {k: round(b.level(now), 1) for k, b in a.buckets().items()} for m, a in self.accounts.items()}

"""Cut the parsed blocks into retrievable pieces at a target size: data/corpus/chunks_<size>.jsonl.

  python -m corpus.chunk --sizes 128 256 512

Rules (ADR: children-only index, carrying their section path):
  * A piece never crosses a section boundary. Consecutive paragraphs of one section are packed up to the target.
  * A paragraph longer than the target is split at sentence boundaries.
  * A table is its own piece. A large table is split into row groups, and each group repeats the caption and the
    header rows, so a number is never separated from what it measures.
  * Figure captions and the abstract are their own pieces.
Every piece carries `cite`, the label the drafter must use and the citation gate checks: "AIAYN §3.2.1",
"AIAYN Table 3", "MOSHI Figure 4", "HNET §A.1", "AIAYN Abstract".
"""
from __future__ import annotations

import argparse
import json
import re
from pathlib import Path

from corpus.build import OUT as BLOCKS, ntok

ROOT = Path(__file__).resolve().parents[1]
SENT = re.compile(r"(?<=[.!?])\s+(?=[A-Z(\"'])")


def cite_of(b: dict) -> str:
    if b["kind"] == "abstract":
        return f"{b['paper']} Abstract"
    if b["float_num"]:
        return f"{b['paper']} {b['float_num']}"
    return f"{b['paper']} §{b['sec_num']}" if b["sec_num"] else f"{b['paper']} \"{b['sec_title']}\""


def split_long(text: str, size: int) -> list[str]:
    out, cur = [], ""
    for s in SENT.split(text):
        if cur and ntok(cur + " " + s) > size:
            out.append(cur)
            cur = s
        else:
            cur = f"{cur} {s}".strip()
    if cur:
        out.append(cur)
    return out


def table_pieces(b: dict, size: int) -> list[str]:
    rows = [r for r in b["text"].split("\n") if r.strip()]
    head = f"{b['float_num']}: {b['caption']}"
    if ntok(head + "\n" + "\n".join(rows)) <= max(size, 200):
        return [head + "\n" + "\n".join(rows)]
    header_rows = rows[:2]
    pieces, cur = [], []
    budget = max(size - ntok(head + "\n" + "\n".join(header_rows)), 60)
    for r in rows[2:]:
        if cur and ntok("\n".join(cur + [r])) > budget:
            pieces.append(cur)
            cur = []
        cur.append(r)
    if cur:
        pieces.append(cur)
    n = len(pieces)
    return [f"{head} (rows part {i + 1}/{n})\n" + "\n".join(header_rows + p) for i, p in enumerate(pieces)]


def chunk(blocks: list[dict], size: int) -> list[dict]:
    pieces, buf = [], []

    def emit(kind: str, b: dict, text: str):
        pieces.append({"id": f"{b['paper']}-{size}-{len(pieces):04d}", "paper": b["paper"], "arxiv": b["arxiv"],
                       "cite": cite_of(b), "kind": kind, "sec_num": b["sec_num"], "sec_path": b["sec_path"],
                       "appendix": b["appendix"], "text": text, "tokens": ntok(text)})

    def flush():
        if buf:
            emit("text", buf[0], "\n".join(x["text"] for x in buf))
            buf.clear()

    for b in blocks:
        if b["kind"] == "text":
            if buf and (buf[0]["paper"], buf[0]["sec_path"]) != (b["paper"], b["sec_path"]):
                flush()
            if b["tokens"] > size:
                flush()
                for part in split_long(b["text"], size):
                    emit("text", b, part)
                continue
            if buf and ntok("\n".join(x["text"] for x in buf + [b])) > size:
                flush()
            buf.append(b)
        else:
            flush()
            if b["kind"] == "table":
                for t in table_pieces(b, size):
                    emit("table", b, t)
            elif b["kind"] in ("figure", "algorithm"):
                emit(b["kind"], b, f"{b['float_num']}: {b['caption']}" + (f"\n{b['text']}" if b["text"] else ""))
            else:   # abstract
                for part in split_long(b["text"], size) if b["tokens"] > size else [b["text"]]:
                    emit("abstract", b, part)
    flush()
    return pieces


def main() -> None:
    ap = argparse.ArgumentParser()
    ap.add_argument("--sizes", nargs="+", type=int, default=[128, 256, 512])
    a = ap.parse_args()
    blocks = [json.loads(l) for l in BLOCKS.read_text(encoding="utf-8").splitlines()]
    for size in a.sizes:
        pieces = chunk(blocks, size)
        out = BLOCKS.parent / f"chunks_{size}.jsonl"
        with out.open("w", encoding="utf-8") as f:
            for p in pieces:
                f.write(json.dumps(p, ensure_ascii=False) + "\n")
        toks = sorted(p["tokens"] for p in pieces)
        print(f"size {size:>4}: {len(pieces):>4} pieces, tokens p50={toks[len(toks) // 2]} max={toks[-1]} "
              f"total={sum(toks):,} -> {out.relative_to(ROOT)}")


if __name__ == "__main__":
    main()

