"""Print the answer key and the three eval answers for the given question ids."""
import json
import sys
from pathlib import Path

R = Path(r"c:\Users\Abhay JK\Downloads\vaani-ai-assignment")
key = {q["id"]: q for q in json.loads((R / "eval" / "answer_key.json").read_text(encoding="utf-8"))["questions"]}
ans = [json.loads(l) for l in (R / "results" / "eval_answers.jsonl").read_text(encoding="utf-8").splitlines()]
out = []
for qid in sys.argv[1:]:
    k = key[qid]
    out.append(f"=================== {qid} answerable={k['answerable']}")
    for i, p in enumerate(k.get("required", []), 1):
        out.append(f"  R{i}: {p['point']}  {p['cites']}")
    if k.get("expected"):
        out.append(f"  EXPECTED: {k['expected']}")
    for t in k.get("traps", []):
        out.append(f"  TRAP: {t}")
    for a in ans:
        if a["qid"] == qid and a.get("scenario") == "eval":
            out.append(f"--- {a['setting']} ({a['request_id']}) branch={a['branch']}")
            for j, s in enumerate(a["sentences"], 1):
                out.append(f"   {j}. {s}")
            for w in a["withheld_sentences"]:
                out.append(f"   [WITHHELD] {w}")
Path(sys.argv[0]).with_name("show_out.txt").write_text("\n".join(out), encoding="utf-8")

