import csv
import json
from collections import Counter
from pathlib import Path

R = Path(r"c:\Users\Abhay JK\Downloads\vaani-ai-assignment")
for sc in ("burst_retry_naive", "burst_retry_policy"):
    rids = {r["request_id"] for r in csv.DictReader((R / "results" / f"pipeline_rows_{sc}.csv").open(encoding="utf-8"))}
    calls, retries, shed = Counter(), 0, Counter()
    with (R / "results" / "trace.jsonl").open(encoding="utf-8") as f:
        for line in f:
            e = json.loads(line)
            if e["rid"] not in rids:
                continue
            if e["ev"] == "call_end":
                calls[(e["model"][-4:], e["status"], e.get("err", "")[:30] if e.get("err") else "")] += 1
            if e["ev"] == "retry_wait_start":
                retries += 1
            if e["ev"] == "shed":
                shed[e["model"][-4:]] += 1
    print(sc, "| drafter calls:", dict(calls), "| retries:", retries, "| shed:", dict(shed))

