import csv, json, collections
from pathlib import Path
root = Path(r"c:\Users\Abhay JK\Downloads\vaani-ai-assignment")
rows = [r for r in csv.DictReader((root / "results.csv").open(encoding="utf-8"))
        if r["scenario"] in ("steady", "burst", "drain", "daily_exhausted", "overload", "tpm_half")]
ids = {r["request_id"]: r for r in rows}
done, reasons = {}, collections.defaultdict(collections.Counter)
with (root / "results" / "trace.jsonl").open(encoding="utf-8") as f:
    for line in f:
        e = json.loads(line)
        rid = e.get("rid")
        if rid not in ids:
            continue
        if e["ev"] == "done":
            done[rid] = e.get("tier")
        if e["ev"] == "admitted" and e.get("tier") not in (None, "full"):
            reasons[rid][str({k: e.get(k) for k in ("tier", "why", "reason", "l1", "pending_full", "drafter_tpd")})] += 1
by = collections.defaultdict(collections.Counter)
for rid, r in ids.items():
    by[(r["scenario"], r["source"])][done.get(rid, "?")] += 1
for k, c in sorted(by.items()):
    print(k, dict(c))
print()
ex = collections.Counter()
for rid, c in reasons.items():
    r = ids[rid]
    if r["source"] == "real":
        for k in c:
            ex[(r["scenario"], k)] += 1
for (sc, k), n in sorted(ex.items())[:12]:
    print(sc, n, k)

