"""Rebuild the text each real load request showed the person, from results/trace.jsonl, for grading.

  python -m eval.load_answers            ->  results/load_answers.jsonl (one line per real load request)

Real load scenarios: steady, burst, drain, daily_exhausted, real_smoke. For each request: the question (matched
exactly to a gold question id), tier, branch, notices, the sentences that passed the gate with their citations,
the sentences withheld, and the extractive quotes. A cache hit replays an earlier Full answer to the same
question: its text is that answer's sentences, taken from the most recent earlier Full answer in the trace that
was cacheable (no withheld or truncated sentence).
"""
from __future__ import annotations

import csv
import json
from collections import defaultdict
from pathlib import Path

from eval.retrieval_scan import load_questions

ROOT = Path(__file__).resolve().parents[1]
SCENARIOS = {"steady", "burst", "drain", "daily_exhausted", "real_smoke"}


def main() -> None:
    rows = [r for r in csv.DictReader((ROOT / "results.csv").open(encoding="utf-8"))
            if r["source"] == "real" and r["scenario"] in SCENARIOS]
    want = {r["request_id"]: r for r in rows}
    qid_of = {q.strip(): qid for qid, q in load_questions().items()}
    ev = defaultdict(list)
    order = []                                  # every request in trace order, for finding a cache hit's source
    with (ROOT / "results" / "trace.jsonl").open(encoding="utf-8") as f:
        for line in f:
            e = json.loads(line)
            rid = e.get("rid")
            if rid is None:
                continue
            if rid not in ev:
                order.append(rid)
            ev[rid].append(e)

    def question(es):
        for e in es:
            if e["ev"] in ("retrieve_start", "cache_hit", "route_start") and e.get("question"):
                return e["question"]
        for e in es:
            if e["ev"] == "retrieve_start" and e.get("iteration") == 0 and "query" in e:
                return e["query"]
        return None

    def answer(es):
        return [{"text": e.get("text"), "cites": e.get("cites", [])} for e in es
                if e["ev"] == "gate_pass" and e.get("kind") == "answer"]

    out, unmatched = [], []
    last_full = {}                              # qid -> sentences of the latest cacheable Full answer so far
    for rid in order:
        es = ev[rid]
        done = next((e for e in es if e["ev"] == "done"), {})
        q = question(es)
        qid = qid_of.get((q or "").strip())
        if done.get("tier") == "full" and not done.get("withheld") and qid:
            last_full_candidate = answer(es)
        else:
            last_full_candidate = None
        if rid in want:
            rec = {"request_id": rid, "scenario": want[rid]["scenario"], "qid": qid, "question": q,
                   "tier": done.get("tier"), "branch": done.get("branch"), "status": want[rid]["status"],
                   "notices": [e["text"] for e in es if e["ev"] == "notice"],
                   "sentences": answer(es),
                   "withheld": [{"text": e.get("text"), "reason": e.get("reason")} for e in es if e["ev"] == "gate_fail"],
                   "other": [{"ev": e["ev"], "kind": e.get("kind"), "text": e.get("text"), "cites": e.get("cites")}
                             for e in es if e["ev"] in ("gate_pass",) and e.get("kind") != "answer"]}
            if done.get("tier") == "cached":
                rec["cached_from"] = last_full.get(qid)
            if not qid:
                unmatched.append(rid)
            out.append(rec)
        if last_full_candidate and qid:
            last_full[qid] = last_full_candidate
    path = ROOT / "results" / "load_answers.jsonl"
    with path.open("w", encoding="utf-8") as f:
        for rec in out:
            f.write(json.dumps(rec, ensure_ascii=False) + "\n")
    by = defaultdict(int)
    for rec in out:
        by[(rec["scenario"], rec["tier"])] += 1
    print(f"{len(out)} of {len(want)} real load requests -> {path.relative_to(ROOT)}; unmatched questions: {unmatched}")
    for k, n in sorted(by.items()):
        print(" ", k, n)
    print("cache hits with no earlier answer found:",
          [r["request_id"] for r in out if r["tier"] == "cached" and not r.get("cached_from")])


if __name__ == "__main__":
    main()

