import json
from collections import defaultdict
from pathlib import Path
root = Path(r"c:\Users\Abhay JK\Downloads\vaani-ai-assignment")
key = {q["id"]: q for q in json.loads((root / "eval" / "answer_key.json").read_text(encoding="utf-8"))["questions"]}
recs = [json.loads(l) for l in (root / "results" / "load_answers.jsonl").open(encoding="utf-8")]
by = defaultdict(list)
for r in recs:
    by[r["qid"]].append(r)
out = []
for qid in sorted(by, key=lambda s: int(s[1:])):
    k = key[qid]
    out.append(f"\n######## {qid} answerable={k['answerable']} n={len(by[qid])}")
    for i, p in enumerate(k["required"], 1):
        out.append(f"  R{i} L{p.get('level')}: {p['point']}  [{', '.join(p.get('cites', []))}]")
    for t in k.get("traps", []):
        out.append(f"  TRAP: {t}")
    for r in by[qid]:
        head = f"-- {r['request_id']} {r['scenario']} {r['tier']} {r['status']}"
        if r["tier"] == "cached":
            out.append(head + f"  = replay of {r['cached_from']['request_id']}")
