import csv, json
from collections import Counter, defaultdict
from pathlib import Path
root = Path(r"c:\Users\Abhay JK\Downloads\vaani-ai-assignment")
key = {q["id"]: q for q in json.loads((root / "eval" / "answer_key.json").read_text(encoding="utf-8"))["questions"]}
g = list(csv.DictReader((root / "results" / "grades_load.csv").open(encoding="utf-8")))
recs = {json.loads(l)["request_id"]: json.loads(l) for l in (root / "results" / "load_answers.jsonl").open(encoding="utf-8")}
by = defaultdict(Counter)
for r in g:
    sc = recs[r["request_id"]]["scenario"]
    if sc == "real_smoke":
        continue
    by[r["setting"]][r["answer_grade"]] += 1
    by["ALL"][r["answer_grade"]] += 1
for t, c in by.items():
    ans = c["correct"] + c["wrong"] + c["refused_wrongly"]
    print(t, dict(c), f"correct of answerable {c['correct']}/{ans} = {100*c['correct']/max(1,ans):.1f}%")
# same-question comparison: full vs lean on questions both answered
pq = defaultdict(lambda: defaultdict(Counter))
for r in g:
    pq[r["qid"]][r["setting"]][r["answer_grade"]] += 1
print()
for q in sorted(pq, key=lambda s: int(s[1:])):
    if key[q]["answerable"]:
        print(q, {t: dict(c) for t, c in pq[q].items()})

